def count_strings(lst):
    if type(lst) != list:
        raise TypeError('Input should be a list')
    d = {}
    for i in lst:
        if type(i) != str:
            raise TypeError('All elements in the list should be strings')
        if i in d:
            d[i] += 1
        else:
            d[i] = 1
    return d

